const items = $input.all();
// เลือกเฉพาะฟิลด์ที่เกี่ยวข้อง (ตัด id / createdAt / updatedAt ของ Data Table ออก)
const records = items.map((i) => {
  const r = i.json;
  return {
    student_name: r.student_name,
    grade_level: r.grade_level,
    subject: r.subject,
    test_name: r.test_name,
    score: r.score,
    total_score: r.total_score,
    percentage: r.percentage,
    pass_status: r.pass_status,
    answer_1: r.answer_1,
    answer_2: r.answer_2,
    answer_3: r.answer_3,
    answer_4: r.answer_4,
    answer_5: r.answer_5,
    answer_6: r.answer_6,
    answer_7: r.answer_7,
    answer_8: r.answer_8,
    answer_9: r.answer_9,
    answer_10: r.answer_10,
    is_correct_1: r.is_correct_1,
    is_correct_2: r.is_correct_2,
    is_correct_3: r.is_correct_3,
    is_correct_4: r.is_correct_4,
    is_correct_5: r.is_correct_5,
    is_correct_6: r.is_correct_6,
    is_correct_7: r.is_correct_7,
    is_correct_8: r.is_correct_8,
    is_correct_9: r.is_correct_9,
    is_correct_10: r.is_correct_10,
    submitted_at: r.submitted_at
  };
});

if (!records || records.length === 0) {
  return [{
    json: {
      error: "ไม่มีข้อมูลผลสอบในตาราง exam_results กรุณาทำข้อสอบผ่านแบบฟอร์มก่อน (และตรวจสอบว่าสร้างตาราง exam_results ผ่านปุ่ม Setup ใน Workshop 2 แล้ว)"
    }
  }];
}

const totalStudents = records.length;
const totalScores = records.reduce((sum, r) => sum + Number(r.score), 0);
const avgScore = (totalScores / totalStudents).toFixed(2);
const maxScore = Math.max(...records.map(r => Number(r.score)));
const minScore = Math.min(...records.map(r => Number(r.score)));
const passCount = records.filter(r => r.pass_status === 'ผ่าน').length;
const failCount = totalStudents - passCount;
const passRate = ((passCount / totalStudents) * 100).toFixed(1);

// สรุปอัตราตอบผิดรายข้อ (1-3) เพื่อให้ AI เห็นว่าข้อไหนนักเรียนพลาดบ่อยที่สุด
const perQuestionWrongRate = Array.from({ length: 10 }, (_, i) => i + 1).map((n) => {
  const answered = records.filter((r) => r[`is_correct_${n}`] !== undefined && r[`is_correct_${n}`] !== null);
  const wrongCount = answered.filter((r) => r[`is_correct_${n}`] === false).length;
  return {
    question: n,
    wrong_count: wrongCount,
    wrong_rate: answered.length ? `${((wrongCount / answered.length) * 100).toFixed(1)}%` : 'N/A'
  };
});

return [{
  json: {
    summary: {
      subject: records[0].subject || 'วิทยาศาสตร์',
      test_name: records[0].test_name || 'แบบทดสอบบทที่ 1',
      total_students: totalStudents,
      avg_score: avgScore,
      max_score: maxScore,
      min_score: minScore,
      pass_count: passCount,
      fail_count: failCount,
      pass_rate: `${passRate}%`,
      per_question_wrong_rate: perQuestionWrongRate
    },
    students_data: records,
    formatted_data_string: JSON.stringify(records, null, 2)
  }
}];
